{"command":"cat << 'EOF' > brute_blake.py
import hashlib, uuid, hmac

target = "efada316814d7d77787f04c7fa1b525f135dcce86d73679582200070901920b0"
secret = b"mysecret"
u = uuid.UUID("00000000-0000-0000-0000-000000000001")

reps_secret = [secret, b"mysecret\0"]
reps_u = [u.bytes, u.bytes_le, str(u).encode(), u.hex.encode(), u.bytes[::-1]]

for s in reps_secret:
    for m in reps_u:
        # blake2s
        if hashlib.blake2s(s + m).hexdigest() == target: print("b2s(s+m)")
        if hashlib.blake2s(m + s).hexdigest() == target: print("b2s(m+s)")

        # blake2b with digest_size=32
        if hashlib.blake2b(s + m, digest_size=32).hexdigest() == target: print("b2b(s+m)")
        if hashlib.blake2b(m + s, digest_size=32).hexdigest() == target: print("b2b(m+s)")

        # HMAC with blake2s/b
        if hmac.new(s, m, hashlib.blake2s).hexdigest() == target: print("HMAC b2s(s, m)")
        if hmac.new(m, s, hashlib.blake2s).hexdigest() == target: print("HMAC b2s(m, s)")

print("Done")
EOF
